package oidc

import (
	"context"
	"crypto/rand"
	"crypto/rsa"
	"encoding/base64"
	"encoding/json"
	"math/big"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	"github.com/golang-jwt/jwt/v5"
	"github.com/stretchr/testify/require"
	"golang.org/x/oauth2"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/observability"
)

// TestNewClient_RejectsBadIssuer ensures discovery against a non-OIDC URL
// fails with a service-unavailable observability error.
func TestNewClient_RejectsBadIssuer(t *testing.T) {
	// Spin up an httptest server that returns 404 for any request — this
	// is a valid HTTP endpoint but is NOT an OIDC issuer, so discovery
	// must fail.
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		http.Error(w, "not found", http.StatusNotFound)
	}))
	defer srv.Close()

	_, err := NewClient(context.Background(), srv.URL, "", "client-id", "client-secret", "http://localhost/cb")
	require.Error(t, err)
	require.True(t, observability.IsCode(err, observability.CodeServiceUnavailable),
		"expected CodeServiceUnavailable, got %v", err)
}

// TestNewClient_DiscoversIssuer stands up a minimal in-test OIDC discovery
// document and confirms NewClient builds a working oauth2.Config.
func TestNewClient_DiscoversIssuer(t *testing.T) {
	mux := http.NewServeMux()

	// Capture the server URL via a closure — we'll set it after srv is built.
	var issuer string

	mux.HandleFunc("/.well-known/openid-configuration", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{
			"issuer":                                issuer,
			"authorization_endpoint":                issuer + "/authorize",
			"token_endpoint":                        issuer + "/token",
			"jwks_uri":                              issuer + "/keys",
			"id_token_signing_alg_values_supported": []string{"RS256"},
			"response_types_supported":              []string{"code"},
			"subject_types_supported":               []string{"public"},
		})
	})

	srv := httptest.NewServer(mux)
	defer srv.Close()
	issuer = srv.URL

	c, err := NewClient(context.Background(), issuer, "", "client-id", "client-secret", "http://localhost/cb")
	require.NoError(t, err)
	require.NotNil(t, c.Provider)
	require.NotNil(t, c.OAuth)
	require.NotNil(t, c.Verifier)

	require.Equal(t, "client-id", c.OAuth.ClientID)
	require.Equal(t, "client-secret", c.OAuth.ClientSecret)
	require.Equal(t, "http://localhost/cb", c.OAuth.RedirectURL)
	require.Equal(t, []string{"openid", "profile", "email", "offline_access"}, c.OAuth.Scopes)
	require.Equal(t, issuer+"/authorize", c.OAuth.Endpoint.AuthURL)
	require.Equal(t, issuer+"/token", c.OAuth.Endpoint.TokenURL)
}

// TestAuthURL_ContainsPKCEParams verifies AuthURL emits the S256 PKCE
// parameters and the supplied state.
func TestAuthURL_ContainsPKCEParams(t *testing.T) {
	mux := http.NewServeMux()
	var issuer string
	mux.HandleFunc("/.well-known/openid-configuration", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{
			"issuer":                                issuer,
			"authorization_endpoint":                issuer + "/authorize",
			"token_endpoint":                        issuer + "/token",
			"jwks_uri":                              issuer + "/keys",
			"id_token_signing_alg_values_supported": []string{"RS256"},
			"response_types_supported":              []string{"code"},
			"subject_types_supported":               []string{"public"},
		})
	})
	srv := httptest.NewServer(mux)
	defer srv.Close()
	issuer = srv.URL

	c, err := NewClient(context.Background(), issuer, "", "client-id", "client-secret", "http://localhost/cb")
	require.NoError(t, err)

	verifier := "pkce-verifier-value"
	url := c.AuthURL("state-key", PKCEChallenge(verifier), "the-oidc-nonce")

	require.Contains(t, url, "state=state-key")
	require.Contains(t, url, "code_challenge="+PKCEChallenge(verifier))
	require.Contains(t, url, "code_challenge_method=S256")
	require.Contains(t, url, "client_id=client-id")
	require.Contains(t, url, "scope=openid+profile+email+offline_access")
	require.Contains(t, url, "access_type=offline")
}

// TestAuthURL_SendsNonce is the F4 regression: the authorization URL must
// carry a real `nonce` parameter distinct from `state`, so the id_token's
// nonce claim can be checked against something the BFF actually sent.
// Previously AuthURL had no nonce param at all.
func TestAuthURL_SendsNonce(t *testing.T) {
	mux := http.NewServeMux()
	var issuer string
	mux.HandleFunc("/.well-known/openid-configuration", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{
			"issuer":                                issuer,
			"authorization_endpoint":                issuer + "/authorize",
			"token_endpoint":                        issuer + "/token",
			"jwks_uri":                              issuer + "/keys",
			"id_token_signing_alg_values_supported": []string{"RS256"},
			"response_types_supported":              []string{"code"},
			"subject_types_supported":               []string{"public"},
		})
	})
	srv := httptest.NewServer(mux)
	defer srv.Close()
	issuer = srv.URL

	c, err := NewClient(context.Background(), issuer, "", "client-id", "client-secret", "http://localhost/cb")
	require.NoError(t, err)

	url := c.AuthURL("state-key", PKCEChallenge("verifier"), "nonce-value-xyz")

	require.Contains(t, url, "nonce=nonce-value-xyz")
	require.NotContains(t, url, "state=nonce-value-xyz",
		"nonce must be distinct from state, not the same value duplicated")
}

// --- Exchange + VerifyIDToken happy path -------------------------------------
//
// Stand up a tiny in-test OIDC issuer that:
//   - serves discovery
//   - serves JWKS (one RSA key)
//   - accepts a token request and returns an access_token + id_token signed
//     with that same key
//
// This lets us exercise Client.Exchange and Client.VerifyIDToken end-to-end.

type testIssuer struct {
	srv    *httptest.Server
	key    *rsa.PrivateKey
	kid    string
	issuer string
}

func newTestIssuer(t *testing.T, clientID string) *testIssuer {
	t.Helper()
	key, err := rsa.GenerateKey(rand.Reader, 2048)
	require.NoError(t, err)

	issuer := &testIssuer{key: key, kid: "test-kid-1"}
	mux := http.NewServeMux()

	mux.HandleFunc("/.well-known/openid-configuration", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{
			"issuer":                                issuer.issuer,
			"authorization_endpoint":                issuer.issuer + "/authorize",
			"token_endpoint":                        issuer.issuer + "/token",
			"jwks_uri":                              issuer.issuer + "/keys",
			"id_token_signing_alg_values_supported": []string{"RS256"},
			"response_types_supported":              []string{"code"},
			"subject_types_supported":               []string{"public"},
		})
	})

	mux.HandleFunc("/keys", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		n := base64.RawURLEncoding.EncodeToString(key.PublicKey.N.Bytes())
		e := base64.RawURLEncoding.EncodeToString(big.NewInt(int64(key.PublicKey.E)).Bytes())
		_ = json.NewEncoder(w).Encode(map[string]any{
			"keys": []map[string]any{{
				"kty": "RSA",
				"alg": "RS256",
				"use": "sig",
				"kid": issuer.kid,
				"n":   n,
				"e":   e,
			}},
		})
	})

	mux.HandleFunc("/token", func(w http.ResponseWriter, r *http.Request) {
		require.NoError(t, r.ParseForm())
		// PKCE code_verifier is required only for the authorization_code
		// grant. The refresh_token grant doesn't send one.
		if r.Form.Get("grant_type") == "authorization_code" && r.Form.Get("code_verifier") == "" {
			http.Error(w, "missing code_verifier", http.StatusBadRequest)
			return
		}

		// Mint an id_token for clientID.
		now := time.Now()
		claims := jwt.MapClaims{
			"iss":   issuer.issuer,
			"aud":   clientID,
			"sub":   "user-123",
			"iat":   now.Unix(),
			"exp":   now.Add(5 * time.Minute).Unix(),
			"nonce": "test-nonce",
		}
		tok := jwt.NewWithClaims(jwt.SigningMethodRS256, claims)
		tok.Header["kid"] = issuer.kid
		signed, err := tok.SignedString(key)
		require.NoError(t, err)

		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{
			"access_token": "test-access-token",
			"token_type":   "Bearer",
			"expires_in":   300,
			"id_token":     signed,
		})
	})

	issuer.srv = httptest.NewServer(mux)
	issuer.issuer = issuer.srv.URL
	return issuer
}

func (i *testIssuer) Close() { i.srv.Close() }

func TestExchange_AndVerifyIDToken(t *testing.T) {
	const clientID = "client-id"
	iss := newTestIssuer(t, clientID)
	defer iss.Close()

	c, err := NewClient(context.Background(), iss.issuer, "", clientID, "client-secret", "http://localhost/cb")
	require.NoError(t, err)

	tok, err := c.Exchange(context.Background(), "auth-code", "pkce-verifier")
	require.NoError(t, err)
	require.Equal(t, "test-access-token", tok.AccessToken)
	require.NotEmpty(t, tok.Extra("id_token"))

	idTok, err := c.VerifyIDToken(context.Background(), tok)
	require.NoError(t, err)
	require.Equal(t, "user-123", idTok.Subject)
}

func TestVerifyIDToken_MissingIDToken(t *testing.T) {
	const clientID = "client-id"
	iss := newTestIssuer(t, clientID)
	defer iss.Close()

	c, err := NewClient(context.Background(), iss.issuer, "", clientID, "client-secret", "http://localhost/cb")
	require.NoError(t, err)

	// Token with no id_token in Extra.
	tok := &oauth2.Token{AccessToken: "x", TokenType: "Bearer"}
	_, err = c.VerifyIDToken(context.Background(), tok)
	require.Error(t, err)
	require.True(t, observability.IsCode(err, observability.CodeForbidden))
}

func TestExchange_TokenEndpointReject(t *testing.T) {
	mux := http.NewServeMux()
	var issuer string
	mux.HandleFunc("/.well-known/openid-configuration", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{
			"issuer":                                issuer,
			"authorization_endpoint":                issuer + "/authorize",
			"token_endpoint":                        issuer + "/token",
			"jwks_uri":                              issuer + "/keys",
			"id_token_signing_alg_values_supported": []string{"RS256"},
			"response_types_supported":              []string{"code"},
			"subject_types_supported":               []string{"public"},
		})
	})
	mux.HandleFunc("/token", func(w http.ResponseWriter, _ *http.Request) {
		http.Error(w, "invalid_grant", http.StatusBadRequest)
	})
	srv := httptest.NewServer(mux)
	defer srv.Close()
	issuer = srv.URL

	c, err := NewClient(context.Background(), issuer, "", "client-id", "client-secret", "http://localhost/cb")
	require.NoError(t, err)

	_, err = c.Exchange(context.Background(), "bad-code", "pkce-verifier")
	require.Error(t, err)
	require.True(t, observability.IsCode(err, observability.CodeForbidden))
}

func TestRefreshAccessToken_EmptyRefresh_ReturnsError(t *testing.T) {
	c := &Client{}
	_, err := c.RefreshAccessToken(context.Background(), "")
	require.Error(t, err)
	require.True(t, observability.IsCode(err, observability.CodeForbidden))
}

func TestRefreshAccessToken_HappyPath(t *testing.T) {
	const clientID = "client-id"
	iss := newTestIssuer(t, clientID)
	defer iss.Close()

	c, err := NewClient(context.Background(), iss.issuer, "", clientID, "client-secret", "http://localhost/cb")
	require.NoError(t, err)

	tok, err := c.RefreshAccessToken(context.Background(), "some-refresh-token")
	require.NoError(t, err)
	require.Equal(t, "test-access-token", tok.AccessToken)
}

func TestRefreshAccessToken_TokenEndpointReject(t *testing.T) {
	mux := http.NewServeMux()
	var issuer string
	mux.HandleFunc("/.well-known/openid-configuration", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{
			"issuer":                                issuer,
			"authorization_endpoint":                issuer + "/authorize",
			"token_endpoint":                        issuer + "/token",
			"jwks_uri":                              issuer + "/keys",
			"id_token_signing_alg_values_supported": []string{"RS256"},
			"response_types_supported":              []string{"code"},
			"subject_types_supported":               []string{"public"},
		})
	})
	mux.HandleFunc("/token", func(w http.ResponseWriter, _ *http.Request) {
		http.Error(w, "invalid_grant", http.StatusBadRequest)
	})
	srv := httptest.NewServer(mux)
	defer srv.Close()
	issuer = srv.URL

	c, err := NewClient(context.Background(), issuer, "", "client-id", "client-secret", "http://localhost/cb")
	require.NoError(t, err)

	_, err = c.RefreshAccessToken(context.Background(), "expired-refresh-token")
	require.Error(t, err)
	require.True(t, observability.IsCode(err, observability.CodeForbidden))
}

// TestEndSessionURL_FromDiscovery verifies EndSessionURL extracts
// end_session_endpoint from the OIDC discovery doc.
func TestEndSessionURL_FromDiscovery(t *testing.T) {
	mux := http.NewServeMux()
	var issuer string
	mux.HandleFunc("/.well-known/openid-configuration", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "application/json")
