// Package oidc wraps OpenID Connect + OAuth2 plumbing for shell-bff.
//
// state.go: persists per-redirect state (state nonce, PKCE verifier,
// post-login return path) in NATS JetStream KV with a TTL so any BFF
// replica can serve the OIDC callback without sticky sessions.
package oidc

import (
	"context"
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"time"

	"github.com/nats-io/nats.go/jetstream"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/observability"
)

// StateBucketName is the name of the NATS KV bucket used for OIDC state.
const StateBucketName = "shell-bff-oidc-state"

// StateBucket persists the per-redirect state {state nonce, PKCE verifier}
// in NATS KV with a TTL. Stateless BFF: any replica can serve the callback.
type StateBucket struct {
	kv jetstream.KeyValue
}

// State holds one in-flight OIDC roundtrip.
type State struct {
	// Nonce is the OIDC nonce: sent as the `nonce` authorize param and
	// asserted against the id_token's `nonce` claim on callback (replay/
	// substitution protection). It is intentionally NOT the KV key — F4
	// (browser-binding + nonce validation fix) found the two conflated,
	// which made "nonce" a misnomer for "state key" and meant no real
	// nonce was ever sent or checked.
	Nonce        string `json:"nonce"`
	PKCEVerifier string `json:"pkce_verifier"`
	ReturnTo     string `json:"return_to"` // path to redirect to after callback
	// BindingHash is HashBindingSecret(secret) for the random secret minted
	// by the login handler and set as a short-lived HttpOnly cookie on the
	// initiating browser. Callback requires the cookie and constant-time
	// compares its hash against this value, so a `state`+`code` pair taken
	// from a leaked URL can't be completed from a different browser. We
	// store only the hash — never the raw secret — so a KV read doesn't
	// hand out a value usable to forge the binding cookie.
	BindingHash string `json:"binding_hash"`
}

// NewStateBucket creates (or opens) the kv bucket "shell-bff-oidc-state"
// with the given TTL.
func NewStateBucket(ctx context.Context, js jetstream.JetStream, ttl time.Duration) (*StateBucket, error) {
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket: StateBucketName,
		TTL:    ttl,
	})
	if err != nil {
		return nil, observability.Wrap(observability.CodeServiceUnavailable, "create kv bucket", err)
	}
	return &StateBucket{kv: kv}, nil
}

// New mints a fresh State, persists it under a random key, and returns
// the key (to embed as the `state` query param in the auth URL).
//
// bindingHash is HashBindingSecret(secret) for the browser-binding secret
// the caller minted and set as a cookie on the initiating browser; it is
// persisted as State.BindingHash for Callback to verify.
func (b *StateBucket) New(ctx context.Context, returnTo, bindingHash string) (key string, st State, err error) {
	verifier := randString(48)
	nonce := randString(24)
	key = randString(24) // independent of the nonce — see State.Nonce doc.
	st = State{Nonce: nonce, PKCEVerifier: verifier, ReturnTo: returnTo, BindingHash: bindingHash}

	body, err := json.Marshal(st)
	if err != nil {
		return "", State{}, observability.Wrap(observability.CodeInternal, "state marshal", err)
	}
	if _, err := b.kv.Put(ctx, key, body); err != nil {
		return "", State{}, observability.Wrap(observability.CodeServiceUnavailable, "kv put", err)
	}
	return key, st, nil
}

// Take retrieves and deletes a state by key. Returns CodeNotFound if missing.
func (b *StateBucket) Take(ctx context.Context, key string) (State, error) {
	entry, err := b.kv.Get(ctx, key)
	if err != nil {
		return State{}, observability.Wrap(observability.CodeNotFound, "kv get state", err)
	}
	var st State
	if err := json.Unmarshal(entry.Value(), &st); err != nil {
		return State{}, observability.Wrap(observability.CodeInternal, "state unmarshal", err)
	}
	if err := b.kv.Delete(ctx, key); err != nil {
		// Soft-fail: if delete races with TTL we don't want to block login.
		_ = err
	}
	return st, nil
}

// PKCEChallenge returns the S256 code_challenge for a verifier
// (RFC 7636 §4.2: BASE64URL-NOPAD(SHA256(ASCII(verifier)))).
func PKCEChallenge(verifier string) string {
	sum := sha256.Sum256([]byte(verifier))
	return base64.RawURLEncoding.EncodeToString(sum[:])
}

// RandomToken returns base64-raw-url encoded n random bytes from
// crypto/rand. Exported so callers outside this package — namely the login
// handler, which mints the browser-binding secret — can reuse the same
// CSPRNG helper instead of rolling their own.
func RandomToken(n int) string {
	return randString(n)
}

// HashBindingSecret returns a SHA-256 hash (base64-raw-url encoded) of a
// browser-binding secret, suitable for storing in State.BindingHash. We
// store the hash, never the raw secret, so a KV read (or its JSON blob
// leaking through logs, backups, etc.) doesn't hand out a value usable to
// forge the binding cookie.
func HashBindingSecret(secret string) string {
	sum := sha256.Sum256([]byte(secret))
	return base64.RawURLEncoding.EncodeToString(sum[:])
}

// randString returns base64-raw-url encoded n random bytes from crypto/rand.
func randString(n int) string {
	b := make([]byte, n)
	if _, err := rand.Read(b); err != nil {
		// crypto/rand.Read on supported platforms only fails if the kernel
		// CSPRNG is unavailable, which is a fatal condition for an auth flow.
		panic(fmt.Sprintf("rand.Read: %v", err))
	}
	return base64.RawURLEncoding.EncodeToString(b)
}


