	// Hand-compute the S256 challenge and confirm encoding (BASE64URL-NOPAD).
	v := "verifier_xyz_123"
	sum := sha256.Sum256([]byte(v))
	want := base64.RawURLEncoding.EncodeToString(sum[:])

	require.Equal(t, want, PKCEChallenge(v))
}

