// transport.go provides a custom http.RoundTripper that rewrites outgoing
// requests so backend code can dial Keycloak via Docker DNS while Keycloak
// still recognizes the instance via its ExternalDomain Host header.
//
// Why this exists:
//
// Keycloak routes requests to instances by Host header. In dev we set
// KEYCLOAK_EXTERNALDOMAIN=localhost so the browser at http://localhost:8080
// works. From inside a Linux container `localhost` is hard-coded to
// 127.0.0.1 (the container itself) regardless of /etc/hosts overrides —
// so containers can't reach Keycloak by dialing `localhost:8080`. Docker
// DNS does resolve the service name `keycloak:8080`, but Keycloak rejects
// any Host header that doesn't match its ExternalDomain.
//
// HostRewriteTransport bridges the two worlds:
//   - the BFF's OIDC client uses the public issuer URL (http://localhost:8080)
//     for discovery + JWT issuer validation
//   - on each request, the transport replaces the URL host with the
//     internal address (keycloak:8080) but keeps the Host header pinned
//     to the public issuer host
//   - Keycloak sees the expected Host header and routes correctly
//   - the JWT issuer claim still matches what the BFF expects to verify
//
// Staging note: when the public issuer URL uses https (e.g.
// https://auth.example.com) but the internal service is plain http (e.g.
// http://keycloak:8080), set both PublicScheme and InternalScheme so that
// RoundTrip rewrites the Scheme in addition to the Host. Without scheme
// rewriting the transport sends a TLS ClientHello to a plain-HTTP server
// and the connection fails with "http: server gave HTTP response to HTTPS
// client".
package oidc

import (
	"bytes"
	"io"
	"net/http"
	"net/url"
	"strings"
)

// HostRewriteTransport rewrites the URL host on outgoing requests but pins
// the Host header to the original (public) host. Useful for service-to-service
// HTTP traffic when the backend is reachable at a different network name
// than the one its TLS cert / Host header allowlist uses.
//
// Set PublicScheme and InternalScheme when the two environments differ in
// scheme (e.g., https public / http internal in staging) so that RoundTrip
// rewrites the Scheme in addition to the Host.
type HostRewriteTransport struct {
	// PublicHost is the host the upstream service expects in the Host
	// header (e.g., "localhost:8080" matching KEYCLOAK_EXTERNALDOMAIN).
	PublicHost string
	// PublicScheme is the scheme of the public issuer URL (e.g., "https").
	// Required only when it differs from InternalScheme.
	PublicScheme string
	// InternalHost is the network address callers can actually dial
	// (e.g., "keycloak:8080" via Docker service-name DNS).
	InternalHost string
	// InternalScheme is the scheme to use when dialing the internal address
	// (e.g., "http"). When non-empty, RoundTrip rewrites the request scheme
	// to this value so that a plain-HTTP backend is not dialed over TLS.
	InternalScheme string
	// Underlying is the wrapped RoundTripper. nil → http.DefaultTransport.
	Underlying http.RoundTripper
}

// RoundTrip rewrites the outbound request URL host while preserving the
// Host header. When InternalScheme is set it also rewrites the URL scheme,
// which is required when the public issuer uses https but the internal
// dial address is plain http (staging mixed-scheme case).
func (t *HostRewriteTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	rt := t.Underlying
	if rt == nil {
		rt = http.DefaultTransport
	}

	if req.URL == nil || t.PublicHost == "" || t.InternalHost == "" || req.URL.Host != t.PublicHost {
		return rt.RoundTrip(req)
	}

	// Clone the request so we don't mutate the caller's req.
	clone := req.Clone(req.Context())
	cloneURL := *req.URL
	cloneURL.Host = t.InternalHost
	if t.InternalScheme != "" {
		cloneURL.Scheme = t.InternalScheme
	}
	clone.URL = &cloneURL
	// Pin the Host header to the public host so the upstream's
	// ExternalDomain check passes.
	clone.Host = t.PublicHost

	return rt.RoundTrip(clone)
}

// orgIDInjectingTransport is a RoundTripper that appends a requested_org_id
// field to every application/x-www-form-urlencoded POST body it forwards.
// Used exclusively by RefreshAccessTokenWithOrgID so the oauth2 library's
// standard refresh-token grant path carries the extra field without forking
// the library.
//
// The transport is single-purpose and intentionally not exported. It must only
// be used for the token endpoint POST — the oauth2 library always sends
// application/x-www-form-urlencoded so content-type sniffing is not required.
type orgIDInjectingTransport struct {
	orgID      string
	underlying http.RoundTripper
}

// RoundTrip clones the request and appends requested_org_id to the form body.
func (t *orgIDInjectingTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	rt := t.underlying
	if rt == nil {
		rt = http.DefaultTransport
	}

	// Only inject into form-encoded POST bodies (token endpoint calls).
	if req.Method != http.MethodPost || req.Body == nil {
		return rt.RoundTrip(req)
	}

	rawBody, err := io.ReadAll(req.Body)
	if err != nil {
		return nil, err
	}
	_ = req.Body.Close()

	// Parse + extend the form.
	vals, err := url.ParseQuery(string(rawBody))
	if err != nil {
		// Not a form body — pass through unmodified.
		clone := req.Clone(req.Context())
		clone.Body = io.NopCloser(bytes.NewReader(rawBody))
		clone.ContentLength = int64(len(rawBody))
		return rt.RoundTrip(clone)
	}
	vals.Set("requested_org_id", t.orgID)
	newBody := vals.Encode()

	clone := req.Clone(req.Context())
	clone.Body = io.NopCloser(strings.NewReader(newBody))
	clone.ContentLength = int64(len(newBody))
	return rt.RoundTrip(clone)
}

// NewHostRewriteClient wraps an http.Client (or builds a fresh one) with a
// HostRewriteTransport. Returns nil if both rewrite hosts are equal or
// either is empty (no rewrite needed).
func NewHostRewriteClient(publicURL, internalURL string, base *http.Client) *http.Client {
	if publicURL == "" || internalURL == "" || publicURL == internalURL {
		return base
	}
	pub, err1 := url.Parse(publicURL)
	intl, err2 := url.Parse(internalURL)
	if err1 != nil || err2 != nil || pub.Host == intl.Host {
		return base
	}
	c := &http.Client{}
	if base != nil {
		c = base
	}
	c.Transport = &HostRewriteTransport{
		PublicHost:     pub.Host,
		PublicScheme:   pub.Scheme,
		InternalHost:   intl.Host,
		InternalScheme: intl.Scheme,
		Underlying:     c.Transport,
	}
	return c
}


