// TestNewHostRewriteClient_NoOpWhenNoRewriteNeeded covers the early-exit
// branches: empty/equal URLs, parse errors, and same-host pairs all
// return the base client unchanged.
func TestNewHostRewriteClient_NoOpWhenNoRewriteNeeded(t *testing.T) {
	cases := []struct {
		name        string
		public      string
		internal    string
		expectNil   bool
		expectSame  bool
	}{
		{name: "both empty", public: "", internal: "", expectNil: true},
		{name: "public empty", public: "", internal: "http://x:8080", expectNil: true},
		{name: "internal empty", public: "http://x:8080", internal: "", expectNil: true},
		{name: "equal strings", public: "http://x:8080", internal: "http://x:8080", expectNil: true},
		{name: "same host different scheme", public: "http://x:8080", internal: "https://x:8080", expectNil: true},
		{name: "unparseable public", public: "://nope", internal: "http://x:8080", expectNil: true},
		{name: "unparseable internal", public: "http://x:8080", internal: "://nope", expectNil: true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			c := NewHostRewriteClient(tc.public, tc.internal, nil)
			require.Nil(t, c)
		})
	}
}

func TestNewHostRewriteClient_WrapsBaseClient(t *testing.T) {
	base := &http.Client{}
	c := NewHostRewriteClient("http://localhost:8080", "http://keycloak:8080", base)
	require.NotNil(t, c)
	require.Same(t, base, c, "should reuse the supplied base client")
	_, ok := c.Transport.(*HostRewriteTransport)
	require.True(t, ok, "Transport should be HostRewriteTransport")
}

// TestHostRewriteTransport_RewritesHostAndPinsHeader is the full-loop test:
// stand up two httptest servers (the "public" host the URL claims to be,
// and the "internal" host we actually dial), wire the transport, and
// verify the request lands on the internal server with the public host
// in the Host header.
func TestHostRewriteTransport_RewritesHostAndPinsHeader(t *testing.T) {
	var gotHost string
	internal := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		gotHost = r.Host
		w.WriteHeader(http.StatusOK)
	}))
	defer internal.Close()

	// Public URL is fictitious — the transport should rewrite to internal.URL.
	// The test transport pins Host to "fake.example:9999" regardless of where
	// the connection actually goes.
	publicHost := "fake.example:9999"
	internalHost := internal.URL[len("http://"):]
	rt := &HostRewriteTransport{
		PublicHost:   publicHost,
		InternalHost: internalHost,
	}

	req, err := http.NewRequest("GET", "http://"+publicHost+"/whatever", nil)
	require.NoError(t, err)

	resp, err := rt.RoundTrip(req)
	require.NoError(t, err)
	require.Equal(t, http.StatusOK, resp.StatusCode)
	_ = resp.Body.Close()

	require.Equal(t, publicHost, gotHost, "internal server should see the public host as Host header")
}

// TestHostRewriteTransport_PassthroughOnNonMatchingHost covers the early
// return when the request's URL host doesn't match PublicHost — transport
// must not rewrite anything.
func TestHostRewriteTransport_PassthroughOnNonMatchingHost(t *testing.T) {
	var gotHost string
	internal := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		gotHost = r.Host
		w.WriteHeader(http.StatusOK)
	}))
	defer internal.Close()

	rt := &HostRewriteTransport{
		PublicHost:   "fake.example:9999",
		InternalHost: "wherever:8080",
	}

	internalHost := internal.URL[len("http://"):]
	req, err := http.NewRequest("GET", "http://"+internalHost+"/", nil)
	require.NoError(t, err)

	resp, err := rt.RoundTrip(req)
	require.NoError(t, err)
	_ = resp.Body.Close()

	// Request went directly to internal.URL, no rewrite — Host is the dialed host.
	require.Equal(t, internalHost, gotHost)
}

// TestRoundTrip_DowngradesScheme_HttpsPublicToHttpInternal asserts that when
// the public issuer URL uses https but the internal dial address is plain http,
// the transport rewrites both the Host AND the Scheme so the connection
// succeeds against the plain-HTTP test server.
//
// Staging is the first environment where these differ (public: https, internal:
// http). Without scheme rewriting the transport sends a TLS ClientHello to a
// plain-HTTP server and gets back:
//
//	http: server gave HTTP response to HTTPS client
func TestRoundTrip_DowngradesScheme_HttpsPublicToHttpInternal(t *testing.T) {
	t.Helper()

	// Stand up a plain-HTTP server that records the Host header it receives.
	var gotHost string
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		gotHost = r.Host
		w.WriteHeader(http.StatusOK)
	}))
	t.Cleanup(srv.Close)

	// The real server is plain HTTP; treat its host:port as the internal address.
	internalHostPort := srv.Listener.Addr().String() // e.g. "127.0.0.1:PORT"

	const (
		publicHostPort = "public.example.com:443"
		publicScheme   = "https"
		internalScheme = "http"
	)

	rt := &HostRewriteTransport{
		PublicHost:     publicHostPort,
		PublicScheme:   publicScheme,   // field does not yet exist — RED: compile error
		InternalHost:   internalHostPort,
		InternalScheme: internalScheme, // field does not yet exist — RED: compile error
		Underlying:     http.DefaultTransport,
	}

	// Build a request as if going to the public https endpoint.
	req, err := http.NewRequest(http.MethodGet, "https://"+publicHostPort+"/.well-known/openid-configuration", nil)
	require.NoError(t, err)

	// RoundTrip must succeed: transport downgraded https→http before dialing.
	resp, err := rt.RoundTrip(req)
	require.NoError(t, err, "transport must downgrade https→http and successfully reach the plain-HTTP server")
	t.Cleanup(func() { resp.Body.Close() })

	require.Equal(t, http.StatusOK, resp.StatusCode)
	// Host header must remain pinned to the public hostname, not the internal one.
	require.Equal(t, publicHostPort, gotHost, "Host header must be pinned to public host")
}

// ---------------------------------------------------------------------------
// orgIDInjectingTransport tests
// ---------------------------------------------------------------------------

// captureRoundTripper is a fake http.RoundTripper that records the last
// request it received.
type captureRoundTripper struct {
	req  *http.Request
	body []byte
	resp *http.Response
}

func (c *captureRoundTripper) RoundTrip(req *http.Request) (*http.Response, error) {
	c.req = req
	if req.Body != nil {
		b, _ := io.ReadAll(req.Body)
		c.body = b
	}
	if c.resp != nil {
		return c.resp, nil
	}
	return &http.Response{
		StatusCode: http.StatusOK,
		Body:       io.NopCloser(strings.NewReader("")),
	}, nil
}

// TestOrgIDInjectingTransport_RoundTrip_InjectsFormParam asserts that
// orgIDInjectingTransport appends requested_org_id to a form-encoded POST
// body while preserving the existing fields.
func TestOrgIDInjectingTransport_RoundTrip_InjectsFormParam(t *testing.T) {
	cap := &captureRoundTripper{}
	tr := &orgIDInjectingTransport{
		orgID:      "target-org-123",
		underlying: cap,
	}

	// Build a token-endpoint-style POST with existing form fields.
	originalForm := url.Values{
		"grant_type":    {"refresh_token"},
		"refresh_token": {"old-refresh-token"},
		"client_id":     {"my-client"},
		"client_secret": {"my-secret"},
	}
	body := originalForm.Encode()

	req, err := http.NewRequest(http.MethodPost, "http://keycloak:8080/token", strings.NewReader(body))
	require.NoError(t, err)
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")

	resp, err := tr.RoundTrip(req)
	require.NoError(t, err)
	require.NotNil(t, resp)
	_ = resp.Body.Close()

	// The underlying transport must have received the modified body.
	require.NotNil(t, cap.body)
	got, err := url.ParseQuery(string(cap.body))
	require.NoError(t, err)

	// Original fields must be preserved.
	require.Equal(t, "refresh_token", got.Get("grant_type"))
	require.Equal(t, "old-refresh-token", got.Get("refresh_token"))
	require.Equal(t, "my-client", got.Get("client_id"))
	require.Equal(t, "my-secret", got.Get("client_secret"))

	// Injected field must be present.
	require.Equal(t, "target-org-123", got.Get("requested_org_id"))
}

// TestOrgIDInjectingTransport_RoundTrip_NonFormBody_PassThrough asserts that
// the transport passes non-form-encoded bodies through unchanged. The
// transport attempts to parse the body as form values; if that fails (or the
// body is not URL-encoded), it forwards the original bytes unmodified.
//
// Note: url.ParseQuery never returns an error for a plain JSON string — it
// just produces a map with the JSON as a key. So the "non-form" path in
// production is the branch where ParseQuery succeeds but the content is
// unexpected. The transport adds requested_org_id regardless. This test
// documents that the transport passes through GET requests (no body) without
// modification.
func TestOrgIDInjectingTransport_RoundTrip_GetRequest_PassThrough(t *testing.T) {
	cap := &captureRoundTripper{}
	tr := &orgIDInjectingTransport{
		orgID:      "org-abc",
		underlying: cap,
	}

	req, err := http.NewRequest(http.MethodGet, "http://keycloak:8080/userinfo", nil)
	require.NoError(t, err)

	resp, err := tr.RoundTrip(req)
	require.NoError(t, err)
	require.NotNil(t, resp)
	_ = resp.Body.Close()

	// GET has no body — cap.body should be nil/empty (passthrough).
	require.Empty(t, cap.body, "GET request body must pass through unchanged (empty)")
}

