package oidc

import (
	"context"
	"net/http"

	"github.com/coreos/go-oidc/v3/oidc"
	"golang.org/x/oauth2"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/observability"
)

// Client wraps oidc.Provider + oauth2.Config for shell-bff's auth flow
// (Authorization Code + PKCE against Keycloak).
type Client struct {
	Provider *oidc.Provider
	OAuth    *oauth2.Config
	Verifier *oidc.IDTokenVerifier
	// HTTPClient carries the optional HostRewriteTransport so token-endpoint
	// POSTs (RefreshAccessToken, Exchange) reach Keycloak via Docker DNS
	// while preserving the public Host header. nil when no rewriting needed.
	HTTPClient *http.Client
}

// NewClient discovers the Keycloak issuer and builds an OAuth2 config.
//
// internalURL is the in-network address Keycloak is reachable at when the
// service-to-service traffic uses Docker service DNS (e.g.
// "http://keycloak:8080"). When set and different from issuerURL, all
// HTTP traffic is wrapped with HostRewriteTransport so containers can
// dial the internal address while Keycloak still recognizes the Host
// header from its ExternalDomain. Pass "" to disable rewriting (e.g.
// in tests).
func NewClient(ctx context.Context, issuerURL, internalURL, clientID, clientSecret, redirectURL string) (*Client, error) {
	// Inject a host-rewriting http.Client into the discovery + token-endpoint
	// HTTP traffic if internalURL is configured.
	if rewriter := NewHostRewriteClient(issuerURL, internalURL, nil); rewriter != nil {
		ctx = oidc.ClientContext(ctx, rewriter)
	}

	provider, err := oidc.NewProvider(ctx, issuerURL)
	if err != nil {
		return nil, observability.Wrap(observability.CodeServiceUnavailable, "oidc.NewProvider", err)
	}
	oauthCfg := &oauth2.Config{
		ClientID:     clientID,
		ClientSecret: clientSecret,
		RedirectURL:  redirectURL,
		Endpoint:     provider.Endpoint(),
		Scopes:       []string{oidc.ScopeOpenID, "profile", "email", "offline_access"},
	}
	verifier := provider.Verifier(&oidc.Config{ClientID: clientID})
	httpClient := NewHostRewriteClient(issuerURL, internalURL, nil)
	return &Client{
		Provider:   provider,
		OAuth:      oauthCfg,
		Verifier:   verifier,
		HTTPClient: httpClient,
	}, nil
}

// AuthURL returns a Keycloak auth-redirect URL for the given state, PKCE
// challenge, and OIDC nonce.
//
// nonce is echoed back in the id_token's `nonce` claim; VerifyIDToken's
// caller must assert it matches the nonce persisted alongside state (F4:
// previously no nonce was sent at all, so the id_token's nonce claim, even
// if checked, would have nothing legitimate to compare against).
func (c *Client) AuthURL(state, codeChallenge, nonce string) string {
	return c.OAuth.AuthCodeURL(state,
		oauth2.AccessTypeOffline,
		oauth2.SetAuthURLParam("code_challenge", codeChallenge),
		oauth2.SetAuthURLParam("code_challenge_method", "S256"),
		oauth2.SetAuthURLParam("nonce", nonce),
	)
}

// EndSessionURL returns Keycloak's RP-initiated logout endpoint
// (end_session_endpoint from the OIDC discovery doc), or "" when the
// provider doesn't advertise one.
//
// Callers redirect the browser to:
//   {endSessionURL}?id_token_hint=...&post_logout_redirect_uri=...
// Keycloak terminates its session, clears its cookies, and redirects to
// post_logout_redirect_uri. This is what makes "Sign in" prompt for
// credentials again instead of silent SSO re-auth.
func (c *Client) EndSessionURL() string {
	var claims struct {
		EndSessionEndpoint string `json:"end_session_endpoint"`
	}
	if err := c.Provider.Claims(&claims); err != nil {
		return ""
	}
	return claims.EndSessionEndpoint
}

// RefreshAccessToken takes a refresh token and returns a fresh oauth2.Token
// (containing a new AccessToken). Used by the cookie-to-bearer middleware
// to mint a fresh access token from the HttpOnly refresh cookie on each
// /api/v1/session request.
func (c *Client) RefreshAccessToken(ctx context.Context, refreshToken string) (*oauth2.Token, error) {
	if refreshToken == "" {
		return nil, observability.New(observability.CodeForbidden, "empty refresh token")
	}
	// Reuse the same host-rewriting client the discovery used so the token
	// endpoint POST also goes via the internal address with the right
	// Host header.
	if c.HTTPClient != nil {
		ctx = oidc.ClientContext(ctx, c.HTTPClient)
	}
	ts := c.OAuth.TokenSource(ctx, &oauth2.Token{RefreshToken: refreshToken})
	tok, err := ts.Token()
	if err != nil {
		return nil, observability.Wrap(observability.CodeForbidden, "refresh token", err)
	}
	return tok, nil
}

// RefreshAccessTokenWithOrgID exchanges a refresh token for a new access token
// whose org_id claim is set to the requested org. The custom Keycloak protocol
// mapper omnicore-org-mapper reads the requested_org_id form parameter, verifies
// the caller's membership, and embeds the chosen org_id in the new token.
//
// Errors:
//   - *oauth2.RetrieveError with Response.StatusCode==403 — caller is not a
//     member of orgID (mapper refused the switch).
//   - *oauth2.RetrieveError with 5xx / other — upstream error.
//   - plain error — network / context failure.
//
// Never logs the refresh token or the returned access/refresh tokens.
func (c *Client) RefreshAccessTokenWithOrgID(ctx context.Context, refreshToken, orgID string) (*oauth2.Token, error) {
	if refreshToken == "" {
		return nil, observability.New(observability.CodeForbidden, "empty refresh token")
	}
	if c.HTTPClient != nil {
		ctx = oidc.ClientContext(ctx, c.HTTPClient)
	}
	// Build a token source that adds requested_org_id as an extra form param.
	// oauth2.Config.TokenSource with RefreshToken set calls the token endpoint
	// with grant_type=refresh_token; SetAuthURLParam appends the extra field.
	// The oauth2 library's internal tokenRequest always sends client_id +
	// client_secret + grant_type + refresh_token for a Refresh grant; we
	// inject the extra param by using a custom token source via Exchange is
	// not available for refresh, so we use Token() on a forked TokenSource
	// that adds the param via the configured endpoint.
	//
	// The cleanest way to inject an extra form param into a refresh-token
	// exchange without reimplementing the oauth2 wire is to construct a
	// one-shot Config with AuthStyle + extra params baked into the Endpoint.
	cfg := *c.OAuth // shallow copy so we don't mutate the shared config
	cfg.Endpoint.AuthStyle = oauth2.AuthStyleInParams
	ts := cfg.TokenSource(ctx, &oauth2.Token{
		RefreshToken: refreshToken,
	})
	// oauth2.ReuseTokenSource wraps a base source; we need to pass the
	// extra param through. The standard library's refresh path uses
	// Config.Exchange-style internals that do not accept extra URL params
	// for refresh grants via the public API.
	//
	// We therefore call the token endpoint directly via
	// oauth2.Config.PasswordCredentialsToken-style approach: construct a
	// custom http request. However, the simplest approach that works without
	// forking the oauth2 library is to embed the requested_org_id via a
	// temporary override of the token URL query string — which Keycloak reads
	// from the POST body form params, not the URL. We use a custom
	// http.RoundTripper that injects the extra body param.
	//
	// Simpler alternative accepted by Keycloak and standard oauth2: use a
	// new oauth2.Config whose Endpoint has the param baked into a custom
	// TokenSource via a wrapped http.Client that appends the field.
	_ = ts // discard the standard source; we use the injecting client below

	// Use a transport that appends requested_org_id to every POST body sent
	// to the token endpoint.
	injectingClient := &http.Client{
		Transport: &orgIDInjectingTransport{
			orgID:      orgID,
			underlying: nil, // defaults to http.DefaultTransport
		},
	}
	if c.HTTPClient != nil {
		injectingClient.Transport = &orgIDInjectingTransport{
			orgID:      orgID,
			underlying: c.HTTPClient.Transport,
		}
	}
	injCtx := oidc.ClientContext(ctx, injectingClient)

	plainTS := c.OAuth.TokenSource(injCtx, &oauth2.Token{RefreshToken: refreshToken})
	tok, err := plainTS.Token()
	if err != nil {
		return nil, err // caller inspects *oauth2.RetrieveError for status
	}
	return tok, nil
}

// Exchange swaps an authorization code (with PKCE verifier) for a token.
func (c *Client) Exchange(ctx context.Context, code, verifier string) (*oauth2.Token, error) {
	if c.HTTPClient != nil {
		ctx = oidc.ClientContext(ctx, c.HTTPClient)
	}
	tok, err := c.OAuth.Exchange(ctx, code,
		oauth2.SetAuthURLParam("code_verifier", verifier),
	)
	if err != nil {
		return nil, observability.Wrap(observability.CodeForbidden, "oauth2 exchange", err)
	}
	return tok, nil
}

// VerifyIDToken extracts and validates the id_token from a token response.
func (c *Client) VerifyIDToken(ctx context.Context, tok *oauth2.Token) (*oidc.IDToken, error) {
	rawID, ok := tok.Extra("id_token").(string)
	if !ok || rawID == "" {
		return nil, observability.New(observability.CodeForbidden, "no id_token in response")
	}
	idTok, err := c.Verifier.Verify(ctx, rawID)
	if err != nil {
		return nil, observability.Wrap(observability.CodeForbidden, "id_token verify", err)
	}
	return idTok, nil
}


