func TestNewClient_RejectsBadIssuer(t *testing.T) {
	// Spin up an httptest server that returns 404 for any request — this
	// is a valid HTTP endpoint but is NOT an OIDC issuer, so discovery
	// must fail.
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		http.Error(w, "not found", http.StatusNotFound)
	}))
	defer srv.Close()

	_, err := NewClient(context.Background(), srv.URL, "", "client-id", "client-secret", "http://localhost/cb")
	require.Error(t, err)
	require.True(t, observability.IsCode(err, observability.CodeServiceUnavailable),
		"expected CodeServiceUnavailable, got %v", err)
}

// TestNewClient_DiscoversIssuer stands up a minimal in-test OIDC discovery
// document and confirms NewClient builds a working oauth2.Config.
func TestNewClient_DiscoversIssuer(t *testing.T) {
	mux := http.NewServeMux()

	// Capture the server URL via a closure — we'll set it after srv is built.
	var issuer string

	mux.HandleFunc("/.well-known/openid-configuration", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{
			"issuer":                                issuer,
			"authorization_endpoint":                issuer + "/authorize",
			"token_endpoint":                        issuer + "/token",
			"jwks_uri":                              issuer + "/keys",
			"id_token_signing_alg_values_supported": []string{"RS256"},
			"response_types_supported":              []string{"code"},
			"subject_types_supported":               []string{"public"},
		})
	})

