// captureRoundTripper is a fake http.RoundTripper that records the last
// request it received.
type captureRoundTripper struct {
	req  *http.Request
	body []byte
	resp *http.Response
}

func (c *captureRoundTripper) RoundTrip(req *http.Request) (*http.Response, error) {
	c.req = req
	if req.Body != nil {
		b, _ := io.ReadAll(req.Body)
		c.body = b
	}
	if c.resp != nil {
		return c.resp, nil
	}
	return &http.Response{
		StatusCode: http.StatusOK,
		Body:       io.NopCloser(strings.NewReader("")),
	}, nil
}

// TestOrgIDInjectingTransport_RoundTrip_InjectsFormParam asserts that
// orgIDInjectingTransport appends requested_org_id to a form-encoded POST
// body while preserving the existing fields.
func TestOrgIDInjectingTransport_RoundTrip_InjectsFormParam(t *testing.T) {
	cap := &captureRoundTripper{}
	tr := &orgIDInjectingTransport{
		orgID:      "target-org-123",
		underlying: cap,
	}

	// Build a token-endpoint-style POST with existing form fields.
	originalForm := url.Values{
		"grant_type":    {"refresh_token"},
		"refresh_token": {"old-refresh-token"},
		"client_id":     {"my-client"},
		"client_secret": {"my-secret"},
	}
	body := originalForm.Encode()

	req, err := http.NewRequest(http.MethodPost, "http://keycloak:8080/token", strings.NewReader(body))
	require.NoError(t, err)
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")

	resp, err := tr.RoundTrip(req)
	require.NoError(t, err)
	require.NotNil(t, resp)
	_ = resp.Body.Close()

	// The underlying transport must have received the modified body.
	require.NotNil(t, cap.body)
	got, err := url.ParseQuery(string(cap.body))
	require.NoError(t, err)

	// Original fields must be preserved.
	require.Equal(t, "refresh_token", got.Get("grant_type"))
	require.Equal(t, "old-refresh-token", got.Get("refresh_token"))
	require.Equal(t, "my-client", got.Get("client_id"))
	require.Equal(t, "my-secret", got.Get("client_secret"))

	// Injected field must be present.
	require.Equal(t, "target-org-123", got.Get("requested_org_id"))
}

// TestOrgIDInjectingTransport_RoundTrip_NonFormBody_PassThrough asserts that
// the transport passes non-form-encoded bodies through unchanged. The
