// TestOrgIDInjectingTransport_RoundTrip_NilUnderlying_UsesDefaultTransport
// asserts that a nil underlying uses http.DefaultTransport (via a real
// httptest server).
func TestOrgIDInjectingTransport_RoundTrip_NilUnderlying_UsesDefaultTransport(t *testing.T) {
	var gotParam string
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		require.NoError(t, r.ParseForm())
		gotParam = r.FormValue("requested_org_id")
